    /* 서버 시간에 맞게 화면 시간 표시 */
    getServerDate: function(timestamp) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var year = timestamp.substr(0, 4); //년도
        var month = parseInt(timestamp.substr(4, 2)) - 1; //월
        var day = timestamp.substr(6, 2); //일
        var hour = timestamp.substr(8, 2); //시간
        var minute = timestamp.substr(10, 2); //분
        var second = timestamp.substr(12, 2); //초


        if(!vm.get('runner')){

            var runner = new Ext.util.TaskRunner(),
                cnt = 0;

            var task = {

                run : function(){
                    var date = new Date(year, month, day, hour, minute, second++),
                        dayOfTheWeek = date.getDay(),
                        week = ['일', '월', '화', '수', '목', '금', '토'],
                        strDay = String(week[dayOfTheWeek]),

                        fullDate = date.getFullYear()  + '.' +
                        (date.getMonth() < 9 ? '0' : '') + (date.getMonth() + 1)  + '.' +
                        (date.getDate() < 10 ? '0' : '') + date.getDate() +
                        '(' + strDay + ')',

                        nowTime = (date.getHours() < 10 ? '0' : '') + date.getHours() + ":" +
                        (date.getMinutes() < 10 ? '0' : '') + date.getMinutes() + ":"+
                        (date.getSeconds() < 10 ? '0' : '') + date.getSeconds();

                    try{
                        if (cnt < 60) {
                            me.getReferences().monitorDate.setHtml(fullDate);
                            me.getReferences().monitorTime.setHtml(nowTime);
                            cnt++;
                        } else {
                            me.onSelect(runner);
                        }
                    } catch(e){
                        runner.stopAll();
                        console.log('timer stop');
                    }

                },

                interval : 1000

            };

            //TASK RUNNER SETTING
            vm.set('runner', runner);
            vm.set('task', task);

            //TASK RUNNER START
            runner.start(task);

        }

    },

    /* 사원 근무지 확인 */
    checkWkplc: function(me, goHome) {
        var me = this,
            vm = me.getViewModel(),
            viewId = me.getViewId(),
            values = {
                hrHrpmEmpId: SecurityUtils.getPrincipal().hrHrpmEmpId,
                stcd : Constants.stcd.NORMAL,
                crtDt : DateUtils.getDate(new Date()),
                wrkDtStrdt : DateUtils.getDate(DateUtils.getFirstDateOfMonth(new Date)),
                wrkDtEdt : DateUtils.getDate(DateUtils.getLastDateOfMonth(new Date)),
                needWrkDtAfterToday : true,
            };

        //근무지 정보 확인
        Ext.Ajax.request({
            headers: {
                serviceId: 'HwmWplSvc.findAllHwmWplInfo',
                viewId: viewId,
                scope: me,
            },
            jsonData: values,
            success: function(res) {
                var result = JSON.parse(res.responseText).page;
                var msg = "";

                if(!Ext.isEmpty(result) && (result.length != 1 || result[0].hrWrkmWkplcId != Constants.wkplcId.EMPTY_WKPLC)){ //근무지있음
                    vm.set('wkplcList', result);

                    // 근무일기준 근무지만 필터링
                    var oldGpsVal = vm.get('workGpsVal'),
                        newGpsVal = [];

                    for (var gpsVal in oldGpsVal) {
                        for (var wkplc in result) {
                            if (result[wkplc].hrWrkmWkplcId == oldGpsVal[gpsVal].hrWrkmWkplcId) {
                                newGpsVal.push(oldGpsVal[gpsVal]);
                                break;
                            }
                        }
                    }
                    vm.set('workGpsVal', newGpsVal);


                    if(goHome) { //퇴근
                        if(!Ext.isEmpty(me.getView())){
                            Ext.Msg.show({
                                message: '지금 퇴근처리 하시겠습니까?<br>주의! 퇴근한 당일은 다시 출근체크를 할 수 없습니다.',
                                title: '퇴근',
                                buttons : {
                                    yes : {itemId : Ext.MessageBox.YES, text : '퇴근'},
                                    no : {itemId : Ext.MessageBox.NO, text : '취소'},
                                },
                                fn: function(btn){
                                    if(btn === 'yes'){
                                        me.getGPS('out');
                                    }
                                }
                            });
                        }
                    }
                    else { //출근
                        if(!Ext.isEmpty(me.getView())){
                            Ext.Msg.show({
                                message: '지금 출근처리 하시겠습니까?<br>',
                                title: '출근',
                                buttons : {
                                    yes : {itemId : Ext.MessageBox.YES, text : '출근'},
                                    no : {itemId : Ext.MessageBox.NO, text : '취소'},
                                },
                                fn: function(btn){
                                    if(btn === 'yes'){
                                        me.getGPS('in');
                                    }
                                }
                            });
                        }
                    }
                }

                else { //근무지없음 :: result값이 없거나, 조회된 근무지 정보가 근무지없음 밖에 없는 경우.

                    msg += "<b>근무지 : 근무지 없음</b><br>";
                    msg += "<b>기간 : -</b><br><br>";
                    msg += "<b style='color:red'>근무지 정보가 다를 경우, </b><br>";
                    msg += "<b style='color:red'>출근체크가 안될수가 있습니다.</b><br>";
                    msg += "정확한 인력현황을 위하여 <br>";
                    msg += "근무지 정보를 최신화 바랍니다.<br>";

                    if(!Ext.isEmpty(me.getView())){
                        Ext.Msg.show({
                            message: msg,
                            title: "근무지 정보 알림",
                            buttons : {
                                yes : {itemId : Ext.MessageBox.YES, text : '변경신청'},
                            },
                            fn: function(btn){
                                if(btn === 'yes'){
                                    var naviView = me.getView().up('navigationview');
                                    me.PUSH_VIEW(naviView, {
                                        menuId  : 'HwmWplAply02M',
                                        title   : '근무지변경 신청',
                                        parentView : me.getView(),
                                        isSubView : true,
                                        records : []
                                    });
                                }
                            }
                        });
                    }
                };
            }
        });
    },

    getServerTime: function(runner) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            values = {};


        // Service 호출
        Ext.Ajax.request({
            headers : {
                viewId : me.getViewId(), // userAlias
                serviceId : 'HwmDaySvc.findAllHwmDayAply'
            },
            jsonData : values,
            scope : me,
            success : function(response) {
                var result = Ext.JSON.decode(response.responseText); // 서버응답결과 JSON 변환

                // Service 성공 했을 경우 기능
                vm.set('runner', null);
                vm.set('task', null);
                runner.stopAll();

                // 실시간 시각 구하기 - 서버 기준
                this.getServerDate(result.timestamp);
            },
            failure : function(response) {
                // Service 실패 했을 경우 기능
                vm.set('runner', null);
                vm.set('task', null);
                runner.stopAll();

                me.HANDLE_RESPONSE_FAILURE(response, opts);
            }

        });
    },

